const ZONE = process.env.TZ;
process.env.TZ = "UTC";
afterAll(() => {
  if (ZONE === undefined) Reflect.deleteProperty(process.env, "TZ");
  else process.env.TZ = ZONE;
});

const here = dirname(fileURLToPath(import.meta.url));
const GOLDENS = join(here, "fixtures/chat-flow");
const WRITE = process.env.VF_WRITE_GOLDENS === "1";
const GENERATED =
  "GENERATED by packages/field-app/test/chat-flow-goldens.test.ts (VF_WRITE_GOLDENS=1): edit the case there, never here";

const fixture = (name: string): Record<string, unknown> =>
  JSON.parse(readFileSync(join(here, "../../contracts/fixtures", `${name}.json`), "utf8"));
const line = (name: string, over: Record<string, unknown> = {}): Record<string, unknown> => ({
  ...fixture(`spark-transcript-line.${name}`),
  ...over,
});

/** A golden as the generator writes it: two-space JSON and a final newline, formatted by nothing else. */
const textOf = (golden: unknown): string => `${JSON.stringify(golden, null, 2)}\n`;

/** Written under `VF_WRITE_GOLDENS=1`; else the committed file must be what the fold says now, byte for byte. */
function holds(file: string, golden: unknown): void {
  const path = join(GOLDENS, file);
  const text = textOf(golden);
  if (WRITE) {
    mkdirSync(GOLDENS, { recursive: true });
    writeFileSync(path, text);
  }
  expect(readFileSync(path, "utf8"), `${file} is not what the fold says now`).toBe(text);
}

