/** The spark as a case gives it: its record, its own run's row (or none), the needs-you queue's open items. */
interface SparkInput {
  readonly spark: SparkSummary;
  readonly row: AgentFieldRow | null;
  readonly items: readonly NeedsItem[];
}

const sparkInput = (
  over: {
    spark?: Partial<SparkSummary>;
    row?: Partial<AgentFieldRow> | null;
    items?: NeedsItem[];
  } = {},
): SparkInput => ({
  spark: spark(over.spark),
  row: over.row === null ? null : row(over.row ?? {}),
  items: over.items ?? [],
});

function entryOf({ spark, row, items }: SparkInput): SparkEntry {
  const entry = sparkEntriesOf([spark], row === null ? [] : [row], { items: [...items] })[0];
  if (entry === undefined) throw new Error("no entry");
  return entry;
}

/** What the fold reads of a spark's entry, and nothing else: the phone derives the same facts from its own entry (the
 * remote cut's row), so the kit's fold takes these. */
function factsOf(entry: SparkEntry) {
  return {
    name: entry.spark.name,
    seed: entry.spark.face.seed,
    status: entry.status,
    ...(entry.spark.turnedAt === undefined ? {} : { turnedAt: entry.spark.turnedAt }),
    new: sparkIsNew(entry),
    awake: entry.awake,
    blocked: entry.blocked,
    waiting: entry.items.length > 0,
    working: entry.run?.alive === true && entry.run.status === "working",
  };
}

