/** `receipts`' spark, read four ways: idle, at work, waiting on you in its pane, and holding an item. */
const RECEIPT_SPARKS = {
  idle: sparkInput(),
  busy: sparkInput({ row: { status: "working" } }),
  asks: sparkInput({
    row: { status: "blocked", blockers: [{ id: "q", kind: "question", since: AT }] },
  }),
  held: sparkInput({ items: [QUESTION] }),
} as const;

function goldenOf(flowCase: FlowCase) {
  const entry = entryOf(flowCase.spark);
  const dropped = flowCase.dropped ?? 0;
  const reading = transcriptReadingOf(flowCase.runs, new Map(Object.entries(flowCase.raw)), {
    dropped,
  });
  const inputs = {
    entry,
    reading,
    pending: flowCase.pending ?? [],
    now: Date.parse(NOW),
    locale: "en-US",
  };
  return {
    "//": GENERATED,
    case: flowCase.name,
    about: flowCase.about,
    input: {
      now: NOW,
      locale: "en-US",
      timeZone: "UTC",
      ...flowCase.spark,
      reading: {
        state: "ready",
        runs: flowCase.runs,
        raw: flowCase.raw,
        dropped,
        whole: false,
      },
      pending: flowCase.pending ?? [],
    },
    facts: factsOf(entry),
    flow: transcriptItemsOf(inputs),
    opened: transcriptItemsOf({ ...inputs, earlier: true }),
    ...(flowCase.name === "receipts" ? receiptsOf() : {}),
  };
}

/** `receiptOf` over every state (none, each of COMPOSE_SAY_STATES, one this build does not know) × the four sparks ×
 * the last bubble or not. */
function receiptsOf() {
  const entries = Object.fromEntries(
    Object.entries(RECEIPT_SPARKS).map(([name, input]) => [name, entryOf(input)]),
  );
  const states = [undefined, ...COMPOSE_SAY_STATES, "migrated"];
  return {
    entries: Object.fromEntries(
      Object.entries(entries).map(([name, entry]) => [name, factsOf(entry)]),
    ),
    receipts: Object.entries(entries).flatMap(([name, entry]) =>
      states.flatMap((state) =>
        [true, false].map((last) => ({
          entry: name,
          state: state ?? null,
          last,
          receipt: receiptOf(state, entry, last),
        })),
      ),
    ),
  };
}

